package io.github.y5c.gebridge;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarbitID;

/**
 * Achievement diary completion, read from the game's completion varbits. Pure: the varbit lookup is passed in.
 *
 * <p>Each tier is complete when its varbit reaches the value the game itself checks for: 1, except Karamja's easy,
 * medium and hard tiers, which the game marks complete at 2.
 */
final class AccountData
{
	static final String[] TIERS = {"easy", "medium", "hard", "elite"};

	/** key, display name, then for each tier: varbit, value meaning complete. */
	static final Object[][] DIARIES = {
		{"ardougne", "Ardougne", VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 1, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, 1, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE, 1},
		{"desert", "Desert", VarbitID.DESERT_DIARY_EASY_COMPLETE, 1, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.DESERT_DIARY_HARD_COMPLETE, 1, VarbitID.DESERT_DIARY_ELITE_COMPLETE, 1},
		{"falador", "Falador", VarbitID.FALADOR_DIARY_EASY_COMPLETE, 1, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.FALADOR_DIARY_HARD_COMPLETE, 1, VarbitID.FALADOR_DIARY_ELITE_COMPLETE, 1},
		{"fremennik", "Fremennik", VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, 1, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, 1, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE, 1},
		{"kandarin", "Kandarin", VarbitID.KANDARIN_DIARY_EASY_COMPLETE, 1, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.KANDARIN_DIARY_HARD_COMPLETE, 1, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE, 1},
		{"karamja", "Karamja", VarbitID.ATJUN_EASY_DONE, 2, VarbitID.ATJUN_MED_DONE, 2,
			VarbitID.ATJUN_HARD_DONE, 2, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE, 1},
		{"kourend_kebos", "Kourend & Kebos", VarbitID.KOUREND_DIARY_EASY_COMPLETE, 1, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.KOUREND_DIARY_HARD_COMPLETE, 1, VarbitID.KOUREND_DIARY_ELITE_COMPLETE, 1},
		{"lumbridge_draynor", "Lumbridge & Draynor", VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, 1, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, 1, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE, 1},
		{"morytania", "Morytania", VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, 1, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, 1, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE, 1},
		{"varrock", "Varrock", VarbitID.VARROCK_DIARY_EASY_COMPLETE, 1, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.VARROCK_DIARY_HARD_COMPLETE, 1, VarbitID.VARROCK_DIARY_ELITE_COMPLETE, 1},
		{"western_provinces", "Western Provinces", VarbitID.WESTERN_DIARY_EASY_COMPLETE, 1, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.WESTERN_DIARY_HARD_COMPLETE, 1, VarbitID.WESTERN_DIARY_ELITE_COMPLETE, 1},
		{"wilderness", "Wilderness", VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, 1, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, 1,
			VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, 1, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE, 1},
	};

	private AccountData()
	{
	}

	/** The diaries block of account.json, in the field layout the Local Data Exporter used. */
	static Map<String, Object> diaries(IntUnaryOperator varbit)
	{
		final Map<String, Object> regions = new LinkedHashMap<>();
		int done = 0;
		int total = 0;
		for (Object[] d : DIARIES)
		{
			final Map<String, Object> r = new LinkedHashMap<>();
			r.put("name", d[1]);
			int rd = 0;
			for (int t = 0; t < TIERS.length; t++)
			{
				final int value = varbit.applyAsInt((Integer) d[2 + 2 * t]);
				final boolean complete = value >= (Integer) d[3 + 2 * t];
				final Map<String, Object> tier = new LinkedHashMap<>();
				tier.put("complete", complete);
				tier.put("value", value);
				r.put(TIERS[t], tier);
				rd += complete ? 1 : 0;
			}
			r.put("completedTierCount", rd);
			r.put("totalTierCount", TIERS.length);
			r.put("allComplete", rd == TIERS.length);
			regions.put((String) d[0], r);
			done += rd;
			total += TIERS.length;
		}
		final Map<String, Object> out = new LinkedHashMap<>();
		out.put("source", "diary completion varbits");
		out.put("completedTierCount", done);
		out.put("totalTierCount", total);
		out.put("completionPercent", total == 0 ? 0 : Math.round(1000.0 * done / total) / 10.0);
		out.put("regions", regions);
		return out;
	}
}

package io.github.y5c.gebridge;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * advice.json: what the player's own tool advises for the Grand Exchange, written by that tool into the plugin's data
 * folder. The plugin only displays it and compares it with what is on screen; it never acts on it.
 *
 * <pre>
 * {"schema": 1, "generatedAt": epoch ms,
 *  "slots":  [{"slot", "itemId", "item", "side", "price", "total", "action", "text"}],   advice for the order now in a slot
 *  "orders": [{"itemId", "item", "side", "price", "qty", "why"}]}                       orders the player should place
 * </pre>
 *
 * A slot entry applies only while that same order (item, side, price, quantity) is still in the slot. An order counts
 * as placed once a slot holds it. {@code qty} may be absent, in which case the quantity is not checked.
 *
 * <p>Pure: no client types. Fields are filled by Gson.
 */
final class Advice
{
	static final int SCHEMA = 1;

	static final class Slot
	{
		int slot = -1;
		int itemId;
		String item;
		String side;
		long price;
		int total;
		String action;
		String text;
	}

	static final class Order
	{
		int itemId;
		String item;
		String side;
		long price;
		Integer qty;
		String why;
	}

	/** What the offer screen shows against the advice: {@code level} is ok, warn or none (no advice for the item). */
	static final class Check
	{
		final String level;
		final List<String> lines;

		Check(String level, List<String> lines)
		{
			this.level = level;
			this.lines = lines;
		}
	}

	int schema;
	long generatedAt;
	List<Slot> slots;
	List<Order> orders;

	boolean usable()
	{
		return schema == SCHEMA && generatedAt > 0;
	}

	List<Slot> slots()
	{
		return slots == null ? Collections.emptyList() : slots;
	}

	List<Order> orders()
	{
		return orders == null ? Collections.emptyList() : orders;
	}

	/** The advice for the order in {@code slot}, or null when there is none or the slot now holds a different order. */
	Slot forSlot(int slot, OfferTracker.Offer o)
	{
		if (o == null || o.isEmpty())
		{
			return null;
		}
		for (Slot s : slots())
		{
			if (s.slot == slot && sameItem(s.itemId, s.item, o) && o.side().equals(s.side) && s.price == o.price && s.total == o.total)
			{
				return s;
			}
		}
		return null;
	}

	/** The slot holding this advised order, or -1. */
	static int placedIn(Order a, OfferTracker.Offer[] now)
	{
		for (int i = 0; i < now.length; i++)
		{
			final OfferTracker.Offer o = now[i];
			if (o != null && !o.isEmpty() && matches(a, o))
			{
				return i;
			}
		}
		return -1;
	}

	/** Advised orders no slot holds yet. */
	List<Order> open(OfferTracker.Offer[] now)
	{
		final List<Order> out = new ArrayList<>();
		for (Order a : orders())
		{
			if (placedIn(a, now) < 0)
			{
				out.add(a);
			}
		}
		return out;
	}

	/**
	 * The offer screen, before Confirm: the item, side and quantity the player has set. The price typed is not compared
	 * here (the client keeps it in a variable RuneLite has not named); it is checked once the order is in its slot.
	 */
	Check check(int itemId, String side, int qty, OfferTracker.Offer[] now)
	{
		final List<String> lines = new ArrayList<>();
		final List<Order> same = new ArrayList<>();
		Order other = null;
		for (Order a : orders())
		{
			if (a.itemId != itemId)
			{
				continue;
			}
			if (side.equals(a.side))
			{
				same.add(a);
			}
			else
			{
				other = a;
			}
		}
		if (same.isEmpty())
		{
			if (other != null)
			{
				lines.add("Advice is to " + other.side + " this item, not " + side);
				lines.add(describe(other));
				return new Check("warn", lines);
			}
			lines.add("No advice for this item");
			return new Check("none", lines);
		}
		boolean qtyOk = false;
		for (Order a : same)
		{
			if (a.qty == null || a.qty == qty)
			{
				qtyOk = true;
			}
		}
		for (Order a : same)
		{
			final int in = placedIn(a, now);
			lines.add(describe(a) + (in >= 0 ? " (already in slot " + in + ")" : ""));
		}
		boolean warn = false;
		if (!qtyOk)
		{
			lines.add("Quantity " + fmt(qty) + " is not the advised " + fmt(same.get(0).qty));
			warn = true;
		}
		for (Order a : same)
		{
			if (placedIn(a, now) >= 0 && same.size() == 1)
			{
				lines.add("This order is already placed: a second one would double it");
				warn = true;
			}
		}
		return new Check(warn ? "warn" : "ok", lines);
	}

	/**
	 * A new order the player has just placed, against the advice for its item and side. Null when it matches an advised
	 * order or there is no advice for it; otherwise the warning to show.
	 */
	String placedMismatch(OfferTracker.Offer o)
	{
		Order near = null;
		for (Order a : orders())
		{
			if (!sameItem(a.itemId, a.item, o) || !o.side().equals(a.side))
			{
				continue;
			}
			if (matches(a, o))
			{
				return null;
			}
			near = a;
		}
		if (near == null)
		{
			return null;
		}
		final List<String> diff = new ArrayList<>();
		if (near.price != o.price)
		{
			diff.add("price " + fmt(o.price) + " (advised " + fmt(near.price) + ")");
		}
		if (near.qty != null && near.qty != o.total)
		{
			diff.add("quantity " + fmt(o.total) + " (advised " + fmt(near.qty) + ")");
		}
		return o.item + ": " + String.join(", ", diff);
	}

	static boolean matches(Order a, OfferTracker.Offer o)
	{
		return sameItem(a.itemId, a.item, o) && o.side().equals(a.side) && a.price == o.price && (a.qty == null || a.qty == o.total);
	}

	private static boolean sameItem(int itemId, String item, OfferTracker.Offer o)
	{
		if (itemId > 0)
		{
			return itemId == o.itemId;
		}
		return item != null && item.equalsIgnoreCase(o.item);
	}

	static String describe(Order a)
	{
		return a.side + " " + (a.qty == null ? "" : fmt(a.qty) + " ") + a.item + " at " + fmt(a.price);
	}

	static String fmt(Number n)
	{
		return n == null ? "?" : String.format(Locale.US, "%,d", n.longValue());
	}

	/** "25m", "3h", "2d": the advice's age. */
	static String age(long ms)
	{
		final long m = Math.max(0, ms / 60_000);
		if (m < 60)
		{
			return m + "m";
		}
		if (m < 48 * 60)
		{
			return (m / 60) + "h";
		}
		return (m / 1440) + "d";
	}
}

package io.github.y5c.gebridge;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** A panel listing the advice while the Grand Exchange is open. Display only. */
final class AdviceOverlay extends OverlayPanel
{
	private static final int WIDTH = 240;

	private final GeBridgePlugin plugin;

	@Inject
	AdviceOverlay(GeBridgePlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final AdviceView v = plugin.adviceView();
		if (v.header == null)
		{
			return null;
		}
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		panelComponent.getChildren().add(TitleComponent.builder().text(v.header).color(v.headerColor).build());
		for (AdviceView.Line l : v.lines)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(l.left).leftColor(l.color)
				.right(l.right == null ? "" : l.right).rightColor(l.color)
				.build());
		}
		return super.render(g);
	}
}

package io.github.y5c.gebridge;

import java.awt.Color;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/** What the two overlays draw, rebuilt on the client thread each tick while the Grand Exchange is open. Immutable. */
final class AdviceView
{
	static final Color OK = new Color(0x7fd27f);
	static final Color WARN = new Color(0xff5c5c);
	static final Color ACT = new Color(0xffd23f);
	static final Color DIM = new Color(0xa0a0a0);
	static final Color TEXT = Color.WHITE;

	static final AdviceView NONE = new AdviceView(null, DIM, Collections.emptyList(), Collections.emptyMap());

	static final class Line
	{
		final String left;
		final String right;
		final Color color;

		Line(String left, String right, Color color)
		{
			this.left = left;
			this.right = right;
			this.color = color;
		}
	}

	final String header;
	final Color headerColor;
	final List<Line> lines;
	// slot -> outline colour
	final Map<Integer, Color> slots;

	AdviceView(String header, Color headerColor, List<Line> lines, Map<Integer, Color> slots)
	{
		this.header = header;
		this.headerColor = headerColor;
		this.lines = lines;
		this.slots = slots;
	}
}

package io.github.y5c.gebridge;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Recognises decanting in an inventory change: potions of one kind leave and potions of the same kind but other dose
 * sizes arrive, with the total number of doses unchanged (Bob Barter's decanting, or combining potions by hand).
 * Pure: works on names and quantities.
 */
final class Decants
{
	private static final Pattern DOSE = Pattern.compile("^(.*)\\((\\d)\\)$");

	private Decants()
	{
	}

	/** One change in quantity of one item: positive arrived, negative left. */
	static final class Change
	{
		final int id;
		final String name;
		final int delta;

		Change(int id, String name, int delta)
		{
			this.id = id;
			this.name = name;
			this.delta = delta;
		}
	}

	/** The decants in one inventory change, one map per potion kind; empty when there are none. */
	static List<Map<String, Object>> find(List<Change> changes)
	{
		final Map<String, List<Change>> byKind = new TreeMap<>();
		for (Change c : changes)
		{
			final Matcher m = c.name == null ? null : DOSE.matcher(c.name);
			if (m != null && m.matches() && c.delta != 0)
			{
				byKind.computeIfAbsent(m.group(1), k -> new ArrayList<>()).add(c);
			}
		}
		final List<Map<String, Object>> out = new ArrayList<>();
		for (Map.Entry<String, List<Change>> k : byKind.entrySet())
		{
			int dosesOut = 0;
			int dosesIn = 0;
			final List<Map<String, Object>> from = new ArrayList<>();
			final List<Map<String, Object>> to = new ArrayList<>();
			for (Change c : k.getValue())
			{
				final int dose = doses(c.name);
				final Map<String, Object> m = new LinkedHashMap<>();
				m.put("id", c.id);
				m.put("name", c.name);
				m.put("quantity", Math.abs(c.delta));
				if (c.delta < 0)
				{
					dosesOut += dose * -c.delta;
					from.add(m);
				}
				else
				{
					dosesIn += dose * c.delta;
					to.add(m);
				}
			}
			if (!from.isEmpty() && !to.isEmpty() && dosesOut == dosesIn)
			{
				final Map<String, Object> d = new LinkedHashMap<>();
				d.put("potion", k.getKey());
				d.put("doses", dosesOut);
				d.put("from", from);
				d.put("to", to);
				out.add(d);
			}
		}
		return out;
	}

	static int doses(String name)
	{
		final Matcher m = DOSE.matcher(name == null ? "" : name);
		return m.matches() ? Integer.parseInt(m.group(2)) : 0;
	}
}

package io.github.y5c.gebridge;

import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

/**
 * The append-only event log, kept to a bounded size.
 *
 * <p>When events.jsonl reaches the size limit it is renamed to events-&lt;UTC time&gt;.jsonl and a new one is started;
 * only the newest {@link #KEEP} archives are kept. A rename keeps the file's identity, so a reader that was part-way
 * through events.jsonl can find the same file under its archive name and finish it. Called on the io thread only.
 */
final class EventLog
{
	static final String LIVE = "events.jsonl";
	static final int KEEP = 6;
	private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss").withZone(ZoneOffset.UTC);

	private EventLog()
	{
	}

	static void append(Filepath dir, String line, long maxBytes, long now) throws IOException
	{
		final Filepath live = dir.joinSegment(LIVE);
		if (live.exists() && live.size() >= maxBytes)
		{
			live.moveTo(dir.joinSegment(archiveName(now)));
			final List<String> names;
			try (Stream<Filepath> files = dir.walk(1))
			{
				names = files.map(Filepath::getFileName).collect(Collectors.toList());
			}
			for (String old : toDelete(names, KEEP))
			{
				dir.joinSegment(old).deleteIfExists();
			}
		}
		live.write(line, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
	}

	static String archiveName(long ms)
	{
		return "events-" + STAMP.format(Instant.ofEpochMilli(ms)) + ".jsonl";
	}

	static boolean isArchive(String name)
	{
		return name != null && name.matches("events-\\d{8}T\\d{6}\\.jsonl");
	}

	/** The archives beyond the newest {@code keep}; the names sort by time. */
	static List<String> toDelete(List<String> names, int keep)
	{
		final List<String> archives = new ArrayList<>();
		for (String n : names)
		{
			if (isArchive(n))
			{
				archives.add(n);
			}
		}
		Collections.sort(archives);
		return archives.size() <= keep ? Collections.emptyList() : archives.subList(0, archives.size() - keep);
	}
}

package io.github.y5c.gebridge;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(GeBridgeConfig.GROUP)
public interface GeBridgeConfig extends Config
{
	String GROUP = "gebridge";

	@ConfigItem(
		keyName = "writeBank",
		name = "Write bank",
		description = "Include the bank and its potion storage (as of the last time the bank was opened) in state.json",
		position = 1
	)
	default boolean writeBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "writeSkills",
		name = "Write skills",
		description = "Include skill levels and experience in state.json",
		position = 2
	)
	default boolean writeSkills()
	{
		return true;
	}

	@ConfigItem(
		keyName = "writeContainers",
		name = "Write inventory and equipment",
		description = "Include the inventory and worn equipment in state.json",
		position = 3
	)
	default boolean writeContainers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "writeAccount",
		name = "Write quests and diaries",
		description = "Write account.json with quest states and achievement diary completion (refreshed every few minutes while logged in)",
		position = 4
	)
	default boolean writeAccount()
	{
		return true;
	}

	@Range(min = 10, max = 300)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "heartbeatSeconds",
		name = "Save interval",
		description = "While logged in, state.json is rewritten at least this often, and at once when something changes",
		position = 5
	)
	default int heartbeatSeconds()
	{
		return 30;
	}

	@Range(min = 1, max = 50)
	@ConfigItem(
		keyName = "maxLogMb",
		name = "Event log size (MB)",
		description = "When events.jsonl reaches this size it is archived and a new one is started; the newest six archives are kept",
		position = 6
	)
	default int maxLogMb()
	{
		return 5;
	}

	@ConfigSection(
		name = "Advice display",
		description = "Shows advice.json, written into this plugin's data folder by your own tool, while the Grand Exchange is open",
		position = 10
	)
	String adviceSection = "advice";

	@ConfigItem(
		keyName = "showAdvice",
		name = "Show advice",
		description = "While the Grand Exchange is open, show the advice from advice.json and check new offers against it",
		position = 11,
		section = adviceSection
